import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { buildComponents, buildSnapshot, computeFingerprint } from "../src/evals/snapshot.js";
import { computeStats } from "../src/evals/stats.js";
import { stageRegressionInputs } from "./helpers/stageRegressionInputs.js";

/**
 * Release 2 gate: a stage eval's stats and fingerprint stay byte-identical to release 1.
 * The snapshot version is 2 because a function revision hash can be part of a snapshot.
 * The golden file was generated by running these inputs through the release 1 code (commit 71dd147c, before any
 * agent story) and the release 2 code, and the two outputs were identical.
 */
const golden = JSON.parse(readFileSync(path.resolve("tests/fixtures/evals/stage-regression.golden.json"), "utf8"));

describe("stage evals are unchanged by release 2", () => {
  const inputs = stageRegressionInputs();

  it("computes the same Stats object, with no agent keys", () => {
    const stats = computeStats(inputs.stats);
    expect(JSON.parse(JSON.stringify(stats))).toEqual(golden.stats);
    expect(Object.keys(stats)).not.toContain("mean_turns");
    expect(Object.keys(stats)).not.toContain("mean_tool_calls");
  });

  it("computes the same components and fingerprint", () => {
    const components = buildComponents(inputs.components);
    expect(JSON.parse(JSON.stringify(components))).toEqual(golden.components);
    expect(computeFingerprint(components)).toBe(golden.fingerprint);
  });

  it("builds the same snapshot JSON", () => {
    expect(JSON.stringify(buildSnapshot(inputs.snapshot))).toBe(JSON.stringify(golden.snapshot));
  });
});
